golden.canonicalQuery:
run: duckdb.table('data/order_items.parquet') -> {
  aggregate:
    total_sales is sale_price.sum()
    items_sold is count()
} -> {
  select:
    total_sales
    items_sold
    avg_selling_price_per_item is round(total_sales / items_sold, 4)
}

run: duckdb.table('data/order_items.parquet') extend {
  join_one: inventory_items is duckdb.table('data/inventory_items.parquet')
    on inventory_item_id = inventory_items.id
} -> {
  aggregate:
    total_sales is sale_price.sum()
    total_cost is inventory_items.cost.sum()
} -> {
  select:
    total_sales
    total_cost
    gross_margin_pct is round((total_sales - total_cost) / total_sales, 6)
}

run: duckdb.table('data/order_items.parquet') extend {
  join_one: inventory_items is duckdb.table('data/inventory_items.parquet')
    on inventory_item_id = inventory_items.id
} -> {
  aggregate:
    total_cost is inventory_items.cost.sum()
    items_sold is count()
} -> {
  select:
    total_cost
    items_sold
    avg_cost_per_item_sold is round(total_cost / items_sold, 4)
}

run: duckdb.table('data/order_items.parquet') -> {
  aggregate:
    total_sales is sale_price.sum()
    customers is count(user_id)
} -> {
  select:
    total_sales
    customers
    avg_spend_per_customer is round(total_sales / customers, 4)
}

run: duckdb.table('data/order_items.parquet') -> {
  group_by: user_id
  aggregate: returned_items is count() { where: status = 'Returned' }
} -> {
  aggregate:
    customers is count()
    customers_with_a_return is count() { where: returned_items > 0 }
} -> {
  select:
    customers
    customers_with_a_return
    customer_return_rate is round(customers_with_a_return / customers, 6)
}

run: duckdb.table('data/order_items.parquet') -> {
  aggregate:
    returned_items is count() { where: status = 'Returned' }
    delivered_items is count() { where: delivered_at is not null }
} -> {
  select:
    returned_items
    delivered_items
    return_share_of_delivered is round(returned_items / delivered_items, 6)
}

run: duckdb.table('data/order_items.parquet') -> {
  aggregate:
    shipped_items is count() { where: shipped_at is not null }
    total_items is count()
} -> {
  select:
    shipped_items
    total_items
    shipped_share is round(shipped_items / total_items, 6)
}

run: duckdb.table('data/order_items.parquet') extend {
  join_one: inventory_items is duckdb.table('data/inventory_items.parquet')
    on inventory_item_id = inventory_items.id
} -> {
  group_by: product_category is inventory_items.product_category
  aggregate:
    total_sales is sale_price.sum()
    margin_dollars is sale_price.sum() - inventory_items.cost.sum()
} -> {
  select:
    product_category
    total_sales
    margin_dollars
    margin_pct is round(margin_dollars / total_sales, 6)
  order_by: margin_pct desc
  limit: 5
}
